SINA_SMART["term1-cardio"] = {"lecture":"term1-cardio","title":"Cardiovascular system terminology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"term1-cardio:e0","text":"Decode: suffix first, then prefix, then combining form(s).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e1","text":"angi/o, vas/o, vascul/o = vessel.","topic":"Combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e2","text":"arteri/o artery; ven/o and phleb/o vein; thromb/o clot; ather/o fatty plaque.","topic":"Combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e3","text":"Endocardium (inner), myocardium (muscle), pericardium (around; visceral = epicardium).","topic":"Walls and structures","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e4","text":"Angina pectoris = ischaemic chest pain; MI = death of myocardial cells.","topic":"Diseases and tests","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e5","text":"CAD: atheromatous coronary arteries.","topic":"Diseases and tests","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e6","text":"CHF: heart cannot pump enough; cardiomegaly: enlarged heart.","topic":"Diseases and tests","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e7","text":"Bradycardia slow; tachycardia fast; fibrillation quivering (defibrillate); asystole = no beat (CPR).","topic":"Diseases and tests","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e8","text":"Vital signs: TPR + BP.","topic":"Diseases and tests","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e9","text":"Troponin rises when myocardial cells die.","topic":"Diseases and tests","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e10","text":"PTCA = coronary angioplasty; CABG = bypass graft.","topic":"Building words and treatments","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"term1-cardio:e11","text":"Aspirin prevents platelet clumping; thrombolytics dissolve clots.","topic":"Building words and treatments","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"xw7t5k":"a","3lcvfs":"a","4mzwuc":"a","16rbps0":"a","1axslm0":"a","1c31jr8":"a","18odlgq":"a","u39hyw":"a","mrjsf8":"a","kwfg68":"a","bre6vs":"a","1nqazz3":"a","10nf252":"a","s9ukjp":"a","fmlaxe":"a","1alp1ie":"a","15d7eap":"a","q5acrz":"a","1x3xdn1":"a","161nd0i":"x"},"mapCounts":{"verified":0,"auto":19,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"term1-cardio:e0":{"s":0,"u":["Decode: suffix first, then prefix, then combining form(s).","To unlock a term, break it into parts and read the meanings in order: suffix first, then prefix, then combining form(s) : cardi/o + -logy = study of the heart."],"dp":[{"h":"Why the suffix changes everything","t":"The same root gives very different meanings depending on the suffix: cardi/o with -logy is a specialty, with -megaly an enlarged heart, with -myopathy a disease of the muscle, with -centesis a puncture. That is why the lecture insists on reading the suffix first: it tells you whether you are looking at a disease, a procedure or a description. Source: the lecture's Medical Language Key."}]},"term1-cardio:e1":{"s":1,"u":["angi/o, vas/o, vascul/o = vessel.","angi/o vessel (angiography: X-ray recording of vessels after contrast); aneurysm/o widening (aneurysmorrhaphy: suturing the dilated wall); aort/o aorta (aortostenosis: narrowing of the aorta); arteri/o artery (arteriosclerosis: abnormal hardening of arterial walls); arteriol/o arteriole (arteriolitis); ather/o fatty plaque (atheroma); atri/o atrium (atrioventricular); cardi/o heart (electrocardiogram: record of the heart's electrical activity); coron/o heart/crown (coronary); phleb/o, ven/o vein (phlebitis, venous); thromb/o blood clot (thrombolysis: breaking up a thrombus); vascul/o, vas/o vessel (vascular, vasospasm); ventricul/o ventricle (intraventricular: within a ventricle)."],"dp":[{"h":"Why so many words for 'vessel'","t":"Medical vocabulary grew from both Greek and Latin: angi/o is Greek, vas/o and vascul/o are Latin, and they coexist in different terms (angiography, vasospasm, vascular). The same happens for vein: phleb/o (Greek, phlebitis) and ven/o (Latin, venous). Recognising both versions is what lets you read any cardiology report. Source: the lecture's combining form tables."}]},"term1-cardio:e2":{"s":1,"u":["arteri/o artery; ven/o and phleb/o vein; thromb/o clot; ather/o fatty plaque.","angi/o vessel (angiography: X-ray recording of vessels after contrast); aneurysm/o widening (aneurysmorrhaphy: suturing the dilated wall); aort/o aorta (aortostenosis: narrowing of the aorta); arteri/o artery (arteriosclerosis: abnormal hardening of arterial walls); arteriol/o arteriole (arteriolitis); ather/o fatty plaque (atheroma); atri/o atrium (atrioventricular); cardi/o heart (electrocardiogram: record of the heart's electrical activity); coron/o heart/crown (coronary); phleb/o, ven/o vein (phlebitis, venous); thromb/o blood clot (thrombolysis: breaking up a thrombus); vascul/o, vas/o vessel (vascular, vasospasm); ventricul/o ventricle (intraventricular: within a ventricle)."],"dp":[]},"term1-cardio:e3":{"s":2,"u":["Endocardium (inner), myocardium (muscle), pericardium (around; visceral = epicardium).","Pericardium (peri- around): a U-shaped sac secreting pericardial fluid; its visceral layer (on the heart) is the epicardium , its outer wall the parietal layer .","Myocardium (my/o muscle): the muscular layer that contracts to pump blood."],"dp":[]},"term1-cardio:e4":{"s":3,"u":["Angina pectoris = ischaemic chest pain; MI = death of myocardial cells.","Angina pectoris : chest pain from myocardial ischaemia (crushing, radiating to neck or left arm, sweating/diaphoresis), a warning of myocardial infarction (MI) , death of myocardial cells."],"dp":[]},"term1-cardio:e5":{"s":3,"u":["CAD: atheromatous coronary arteries.","Coronary artery disease (CAD) : coronary arteriosclerosis with atheromatous plaque.","Acute coronary syndrome (ACS) : acute myocardial ischaemia from a clot in a coronary artery."],"dp":[]},"term1-cardio:e6":{"s":3,"u":["CHF: heart cannot pump enough; cardiomegaly: enlarged heart.","Congestive heart failure (CHF) : inability to pump enough blood.","Cardiomegaly : enlargement of the heart."],"dp":[]},"term1-cardio:e7":{"s":3,"u":["Bradycardia slow; tachycardia fast; fibrillation quivering (defibrillate); asystole = no beat (CPR).","Arrhythmia (irregular rate or rhythm), bradycardia (slow), fibrillation (fast uncoordinated quivering; ventricular fibrillation needs defibrillation), asystole (no heartbeat: CPR)."],"dp":[]},"term1-cardio:e8":{"s":3,"u":["Vital signs: TPR + BP.","Vital signs : temperature, pulse, respirations (TPR) and blood pressure."],"dp":[]},"term1-cardio:e9":{"s":3,"u":["Troponin rises when myocardial cells die.","Tests: CRP (inflammation), lipid profile , troponin (released when myocardial cells die), cardiac catheterisation , echocardiography and transoesophageal echocardiography (TEE) .","Angina pectoris : chest pain from myocardial ischaemia (crushing, radiating to neck or left arm, sweating/diaphoresis), a warning of myocardial infarction (MI) , death of myocardial cells."],"dp":[]},"term1-cardio:e10":{"s":4,"u":["PTCA = coronary angioplasty; CABG = bypass graft.","Procedures : valve replacement, valvuloplasty (valvotomy), PTCA (percutaneous transluminal coronary angioplasty), CABG (coronary artery bypass graft); thoracotomy, sternotomy, cardiotomy, thrombectomy."],"dp":[]},"term1-cardio:e11":{"s":4,"u":["Aspirin prevents platelet clumping; thrombolytics dissolve clots.","Drugs : ACE inhibitors (heart failure, hypertension), antiarrhythmics, antihypertensives, aspirin (prevents clots by keeping platelets from sticking), beta-blockers (angina, hypertension), thrombolytics (dissolve a blocking clot)."],"dp":[]}},"meta":{"xw7t5k":{"a":"recall","vg":"term1-cardio:e0/recall/1"},"3lcvfs":{"a":"recall","vg":"term1-cardio:e0/recall/2"},"4mzwuc":{"a":"recall","vg":"term1-cardio:e1/recall/1"},"16rbps0":{"a":"recall","vg":"term1-cardio:e1/recall/2"},"1axslm0":{"a":"recall","vg":"term1-cardio:e2/recall/1"},"1c31jr8":{"a":"recall","vg":"term1-cardio:e1/recall/3"},"18odlgq":{"a":"recall","vg":"term1-cardio:e2/recall/2"},"u39hyw":{"a":"recall","vg":"term1-cardio:e3/recall/1"},"mrjsf8":{"a":"recall","vg":"term1-cardio:e3/recall/1"},"kwfg68":{"a":"recall","vg":"term1-cardio:e1/recall/4"},"bre6vs":{"a":"recall","vg":"term1-cardio:e4/recall/1"},"1nqazz3":{"a":"recall","vg":"term1-cardio:e4/recall/1"},"10nf252":{"a":"recall","vg":"term1-cardio:e7/recall/1"},"s9ukjp":{"a":"recall","vg":"term1-cardio:e7/recall/2"},"fmlaxe":{"a":"recall","vg":"term1-cardio:e8/recall/1"},"1alp1ie":{"a":"recall","vg":"term1-cardio:e9/recall/1"},"15d7eap":{"a":"recall","vg":"term1-cardio:e10/recall/1"},"q5acrz":{"a":"recall","vg":"term1-cardio:e11/recall/1"},"1x3xdn1":{"a":"recall","vg":"term1-cardio:e5/recall/1"}},"explRev":"30c7e6485f46"};
